using System;using System.Linq;using System.Text.Json;using System.Collections.Generic;using Observatory.UI;
class Program {static void Main(){var captures=new List<object>();for(int rotate=0;rotate<7;rotate++){var input=new[]{new{Id="a",Text="Body 10",Group="00000000-0000-0000-0000-000000000001"},new{Id="b",Text="Body 2",Group="00000000-0000-0000-0000-000000000001"},new{Id="c",Text="Body 30",Group="00000000-0000-0000-0000-000000000001"},new{Id="d",Text="Body 1",Group=""},new{Id="e",Text="Body 5",Group="00000000-0000-0000-0000-000000000002"},new{Id="f",Text="Body 7",Group="00000000-0000-0000-0000-000000000002"},new{Id="g",Text="Body 6",Group=""}};input=input.Skip(rotate).Concat(input.Take(rotate)).ToArray();var grid=new PluginUIGrid();foreach(var row in input)grid.Add(row.Id,row.Text,row.Group);var before=grid.Order();grid.Click(0);var ascending=grid.Order();grid.Click(0);var descending=grid.Order();grid.Click(0);var third=grid.Order();captures.Add(new{input,before,ascending,descending,third});}Console.Write(JsonSerializer.Serialize(captures));}}
